// IDs "marcados" com template literal types
type IdEncomenda = `enc-${number}`;
type IdProduto = `prod-${string}`;
type DataISO = `${number}-${number}-${number}`;

interface Linha {
  readonly produto: IdProduto;
  readonly quantidade: number;
  readonly precoCentimos: number;
}

interface BaseEncomenda {
  readonly id: IdEncomenda;
  readonly cliente: string;
  readonly linhas: readonly Linha[];
  readonly criadaEm: DataISO;
}

// Cada estado traz só os campos que fazem sentido nele
interface Pendente extends BaseEncomenda { readonly estado: "pendente" }
interface Paga extends BaseEncomenda {
  readonly estado: "paga";
  readonly pagaEm: DataISO;
  readonly referencia: string;
}
interface Enviada extends Omit<Paga, "estado"> {
  readonly estado: "enviada";
  readonly codigoEnvio: string;
}
interface Cancelada extends BaseEncomenda {
  readonly estado: "cancelada";
  readonly motivo: string;
}

type Encomenda = Pendente | Paga | Enviada | Cancelada;

// Tipos derivados, nunca reescritos à mão
type Estado = Encomenda["estado"];                        // "pendente" | "paga" | "enviada" | "cancelada"
type NovaEncomenda = Omit<Pendente, "id" | "estado" | "criadaEm">;
type Resumo = Pick<Encomenda, "id" | "cliente" | "estado">;

function totalCentimos(e: Encomenda): number {
  return e.linhas.reduce((soma, l) => soma + l.quantidade * l.precoCentimos, 0);
}

const pedido: NovaEncomenda = {
  cliente: "Ana Sousa",
