const enc: Pendente = { ...pedido, id: "enc-1", estado: "pendente", criadaEm: "2026-03-02" };
const resumo: Resumo = { id: enc.id, cliente: enc.cliente, estado: enc.estado };

console.log(resumo);             // { id: 'enc-1', cliente: 'Ana Sousa', estado: 'pendente' }
console.log(totalCentimos(enc)); // 2990

type IdEncomenda = `enc-${number}`;
type DataISO = `${number}-${number}-${number}`;
interface Linha { readonly produto: string; readonly quantidade: number; readonly precoCentimos: number }
interface BaseEncomenda { readonly id: IdEncomenda; readonly cliente: string; readonly linhas: readonly Linha[] }
interface Pendente extends BaseEncomenda { readonly estado: "pendente" }
interface Paga extends BaseEncomenda { readonly estado: "paga"; readonly pagaEm: DataISO; readonly referencia: string }
interface Enviada extends Omit<Paga, "estado"> { readonly estado: "enviada"; readonly codigoEnvio: string }
interface Cancelada extends BaseEncomenda { readonly estado: "cancelada"; readonly motivo: string }
type Encomenda = Pendente | Paga | Enviada | Cancelada;
type Estado = Encomenda["estado"];
type EncomendaEm<S extends Estado> = Extract<Encomenda, { estado: S }>;

// Cada transição só aceita o estado de partida certo
function pagar(e: Pendente, referencia: string, pagaEm: DataISO): Paga {
  return { ...e, estado: "paga", referencia, pagaEm };
}

function enviar(e: Paga, codigoEnvio: string): Enviada {
  return { ...e, estado: "enviada", codigoEnvio };
}

// Cancelar aceita dois estados de partida, e só esses
function cancelar(e: EncomendaEm<"pendente" | "paga">, motivo: string): Cancelada {
  const { id, cliente, linhas } = e;
  return { id, cliente, linhas, estado: "cancelada", motivo };
}

// Type predicate: estreita uma Encomenda qualquer para as canceláveis
function podeCancelar(e: Encomenda): e is Pendente | Paga {
  return e.estado === "pendente" || e.estado === "paga";
}

// Switch exaustivo: um estado novo sem case faz o default deixar de compilar
function descrever(e: Encomenda): string {
  switch (e.estado) {
    case "pendente":
      return `${e.id}: à espera de pagamento`;
    case "paga":
      return `${e.id}: paga (ref. ${e.referencia})`;
    case "enviada":
      return `${e.id}: enviada com o código ${e.codigoEnvio}`;
    case "cancelada":
      return `${e.id}: cancelada (${e.motivo})`;
    default: {
      const impossivel: never = e;
      return impossivel;
    }
  }
}

const nova: Pendente = {
  id: "enc-7", cliente: "Rui Lopes", estado: "pendente",
  linhas: [{ produto: "prod-cha", quantidade: 3, precoCentimos: 450 }],
};
const paga = pagar(nova, "MB-5521", "2026-03-03");
const enviada = enviar(paga, "CTT-RR123");

const historico: Encomenda[] = [nova, paga, enviada];
for (const e of historico) {
  console.log(descrever(e));
}
// enc-7: à espera de pagamento
// enc-7: paga (ref. MB-5521)
// enc-7: enviada com o código CTT-RR123

function tentarCancelar(e: Encomenda, motivo: string): string {
  if (podeCancelar(e)) return descrever(cancelar(e, motivo));
  return `${e.id} já não pode ser cancelada (está ${e.estado})`;
}

console.log(tentarCancelar(enviada, "desistência")); // enc-7 já não pode ser cancelada (está enviada)
console.log(tentarCancelar(nova, "sem stock"));      // enc-7: cancelada (sem stock)

type IdEncomenda = `enc-${number}`;
type IdProduto = `prod-${string}`;
type DataISO = `${number}-${number}-${number}`;
type Resultado<T, E> = { ok: true; valor: T } | { ok: false; erro: E };

// Os blocos de construção do módulo 10
type Validador<T> = (x: unknown) => x is T;
type TipoDe<V> = V extends Validador<infer T> ? T : never;

const eString: Validador<string> = (x): x is string => typeof x === "string";
const eInteiroPositivo: Validador<number> = (x): x is number =>
  typeof x === "number" && Number.isInteger(x) && x > 0;

function ePadrao<T extends string>(regex: RegExp): Validador<T> {
  return (x): x is T => typeof x === "string" && regex.test(x);
}

function eLiteral<const L extends readonly string[]>(...valores: L): Validador<L[number]> {
  return (x): x is L[number] => valores.includes(x as L[number]);
}

function eArrayDe<T>(v: Validador<T>): Validador<T[]> {
  return (x): x is T[] => Array.isArray(x) && x.every(v);
}

function eObjeto<E extends Record<string, Validador<unknown>>>(
  esquema: E
): Validador<{ [K in keyof E]: TipoDe<E[K]> }> {
  return (x): x is { [K in keyof E]: TipoDe<E[K]> } => {
    if (typeof x !== "object" || x === null) return false;
    const o = x as Record<string, unknown>;
    return Object.keys(esquema).every((chave) => esquema[chave](o[chave]));
  };
}

// Validadores dos IDs e das datas: o regex garante o que o template literal promete
const eIdEncomenda = ePadrao<IdEncomenda>(/^enc-\d+$/);
const eIdProduto = ePadrao<IdProduto>(/^prod-[a-z-]+$/);
const eDataISO = ePadrao<DataISO>(/^\d{4}-\d{2}-\d{2}$/);

// O esquema de uma encomenda acabada de chegar (só pode vir pendente)
const eEncomendaRecebida = eObjeto({
  id: eIdEncomenda,
  cliente: eString,
  estado: eLiteral("pendente"),
  criadaEm: eDataISO,
  linhas: eArrayDe(eObjeto({ produto: eIdProduto, quantidade: eInteiroPositivo, precoCentimos: eInteiroPositivo })),
});

// O tipo sai do esquema: um só sítio para mudar
type EncomendaRecebida = TipoDe<typeof eEncomendaRecebida>;

type ErroLeitura =
  | { tipo: "json-invalido" }
  | { tipo: "formato-invalido"; dados: unknown };

function lerEncomenda(texto: string): Resultado<EncomendaRecebida, ErroLeitura> {
  let dados: unknown;
  try {
    dados = JSON.parse(texto);
  } catch {
    return { ok: false, erro: { tipo: "json-invalido" } };
  }
  if (!eEncomendaRecebida(dados)) return { ok: false, erro: { tipo: "formato-invalido", dados } };
  return { ok: true, valor: dados };
}

