type Resultado<T, E> = { ok: true; valor: T } | { ok: false; erro: E };

type ErroRepositorio =
  | { tipo: "nao-encontrado"; id: string }
  | { tipo: "duplicado"; id: string };

// O contrato: qualquer entidade com um id em string
interface Repositorio<T extends { readonly id: string }> {
  obter(id: T["id"]): Promise<Resultado<T, ErroRepositorio>>;
  inserir(item: T): Promise<Resultado<T, ErroRepositorio>>;
  substituir(item: T): Promise<Resultado<T, ErroRepositorio>>;
  listar(): Promise<readonly T[]>;
}

const pausa = (ms: number) => new Promise<void>((resolver) => setTimeout(resolver, ms));

// Uma implementação em memória, com uma latência simulada de poucos ms
class RepositorioEmMemoria<T extends { readonly id: string }> implements Repositorio<T> {
  private readonly itens = new Map<T["id"], T>();

  constructor(private readonly latenciaMs: number = 5) {}

  async obter(id: T["id"]): Promise<Resultado<T, ErroRepositorio>> {
    await pausa(this.latenciaMs);
    const item = this.itens.get(id);
    return item ? { ok: true, valor: item } : { ok: false, erro: { tipo: "nao-encontrado", id } };
  }

  async inserir(item: T): Promise<Resultado<T, ErroRepositorio>> {
    await pausa(this.latenciaMs);
    if (this.itens.has(item.id)) return { ok: false, erro: { tipo: "duplicado", id: item.id } };
    this.itens.set(item.id, item);
    return { ok: true, valor: item };
  }

  async substituir(item: T): Promise<Resultado<T, ErroRepositorio>> {
    await pausa(this.latenciaMs);
    if (!this.itens.has(item.id)) return { ok: false, erro: { tipo: "nao-encontrado", id: item.id } };
    this.itens.set(item.id, item);
    return { ok: true, valor: item };
  }

  async listar(): Promise<readonly T[]> {
    await pausa(this.latenciaMs);
    return [...this.itens.values()];
  }
}

function explicar(erro: ErroRepositorio): string {
  switch (erro.tipo) {
    case "nao-encontrado":
      return `não existe nenhum registo ${erro.id}`;
    case "duplicado":
      return `já existe um registo ${erro.id}`;
  }
}

// O mesmo repositório serve qualquer entidade que cumpra a constraint
interface Produto {
  readonly id: `prod-${string}`;
  readonly nome: string;
  readonly precoCentimos: number;
}

const produtos: Repositorio<Produto> = new RepositorioEmMemoria<Produto>();

await produtos.inserir({ id: "prod-caneca", nome: "Caneca", precoCentimos: 850 });
const repetido = await produtos.inserir({ id: "prod-caneca", nome: "Outra caneca", precoCentimos: 900 });
if (!repetido.ok) console.log(explicar(repetido.erro)); // já existe um registo prod-caneca

const procurado = await produtos.obter("prod-bule");
if (!procurado.ok) console.log(explicar(procurado.erro)); // não existe nenhum registo prod-bule

const caneca = await produtos.obter("prod-caneca");
if (caneca.ok) console.log(caneca.valor.nome); // Caneca

console.log((await produtos.listar()).length); // 1

// ---- tipos (tipos.ts), versão compacta ----
type IdEncomenda = `enc-${number}`;
type DataISO = `${number}-${number}-${number}`;
type Resultado<T, E> = { ok: true; valor: T } | { ok: false; erro: E };
interface Linha { readonly produto: string; readonly quantidade: number; readonly precoCentimos: number }
interface BaseEncomenda { readonly id: IdEncomenda; readonly cliente: string; readonly linhas: readonly Linha[] }
interface Pendente extends BaseEncomenda { readonly estado: "pendente" }
interface Paga extends BaseEncomenda { readonly estado: "paga"; readonly referencia: string; readonly pagaEm: DataISO }
interface Enviada extends Omit<Paga, "estado"> { readonly estado: "enviada"; readonly codigoEnvio: string }
interface Cancelada extends BaseEncomenda { readonly estado: "cancelada"; readonly motivo: string }
type Encomenda = Pendente | Paga | Enviada | Cancelada;
type Estado = Encomenda["estado"];

// ---- repositório (repositorio.ts), versão compacta ----
type ErroRepositorio = { tipo: "nao-encontrado"; id: string } | { tipo: "duplicado"; id: string };
const pausa = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

class RepositorioEmMemoria<T extends { readonly id: string }> {
  private readonly itens = new Map<T["id"], T>();
  async obter(id: T["id"]): Promise<Resultado<T, ErroRepositorio>> {
    await pausa(2);
    const item = this.itens.get(id);
    return item ? { ok: true, valor: item } : { ok: false, erro: { tipo: "nao-encontrado", id } };
  }
  // Genérico no método: guardar uma Paga devolve uma Paga, não uma Encomenda
  async guardar<U extends T>(item: U): Promise<U> {
    await pausa(2);
    this.itens.set(item.id, item);
    return item;
  }
  async listar(): Promise<readonly T[]> {
    await pausa(2);
    return [...this.itens.values()];
  }
}

// ---- serviço (servico.ts) ----
type ErroServico =
  | ErroRepositorio
  | { tipo: "transicao-invalida"; id: IdEncomenda; de: Estado; acao: "pagar" | "enviar" };

const totalCentimos = (e: Encomenda) =>
  e.linhas.reduce((s, l) => s + l.quantidade * l.precoCentimos, 0);

class ServicoEncomendas {
  constructor(private readonly repo: RepositorioEmMemoria<Encomenda>) {}

  registar(e: Pendente): Promise<Pendente> {
    return this.repo.guardar(e).then(() => e);
  }

  async pagar(id: IdEncomenda, referencia: string, pagaEm: DataISO): Promise<Resultado<Paga, ErroServico>> {
    const r = await this.repo.obter(id);
    if (!r.ok) return r;
    const e = r.valor;
    if (e.estado !== "pendente") {
      return { ok: false, erro: { tipo: "transicao-invalida", id, de: e.estado, acao: "pagar" } };
    }
    const paga: Paga = { ...e, estado: "paga", referencia, pagaEm };
    return { ok: true, valor: await this.repo.guardar(paga) };
  }

  async enviar(id: IdEncomenda, codigoEnvio: string): Promise<Resultado<Enviada, ErroServico>> {
    const r = await this.repo.obter(id);
    if (!r.ok) return r;
    const e = r.valor;
    if (e.estado !== "paga") {
      return { ok: false, erro: { tipo: "transicao-invalida", id, de: e.estado, acao: "enviar" } };
    }
    const enviada: Enviada = { ...e, estado: "enviada", codigoEnvio };
    return { ok: true, valor: await this.repo.guardar(enviada) };
  }

  // Sem anotação de retorno: o tipo é inferido e derivado mais abaixo
  async relatorio() {
    const porEstado: { [S in Estado]: { quantidade: number; centimos: number } } = {
      pendente: { quantidade: 0, centimos: 0 },
      paga: { quantidade: 0, centimos: 0 },
      enviada: { quantidade: 0, centimos: 0 },
      cancelada: { quantidade: 0, centimos: 0 },
    };
    const porCliente: Record<string, number> = {};
    for (const e of await this.repo.listar()) {
      porEstado[e.estado].quantidade += 1;
      porEstado[e.estado].centimos += totalCentimos(e);
      if (e.estado !== "cancelada") {
        porCliente[e.cliente] = (porCliente[e.cliente] ?? 0) + totalCentimos(e);
      }
    }
    return { porEstado, porCliente };
  }
}

type Relatorio = Awaited<ReturnType<ServicoEncomendas["relatorio"]>>;

function descreverErro(erro: ErroServico): string {
  switch (erro.tipo) {
    case "nao-encontrado":
      return `${erro.id} não existe`;
    case "duplicado":
      return `${erro.id} está repetida`;
    case "transicao-invalida":
      return `não é possível ${erro.acao} ${erro.id}: está ${erro.de}`;
    default: {
      const impossivel: never = erro;
      return impossivel;
    }
  }
}

const euros = (centimos: number) => `${(centimos / 100).toFixed(2)} €`;

function formatar(r: Relatorio): string[] {
  const estados = Object.keys(r.porEstado) as Estado[];
  const linhas = estados.map((s) => {
    const { quantidade, centimos } = r.porEstado[s];
    return `${s.padEnd(10)} ${String(quantidade).padStart(2)} ${euros(centimos).padStart(9)}`;
  });
  for (const [cliente, c] of Object.entries(r.porCliente)) linhas.push(`${cliente}: ${euros(c)}`);
  return linhas;
}

// ---- main.ts ----
const servico = new ServicoEncomendas(new RepositorioEmMemoria<Encomenda>());

await servico.registar({ id: "enc-1", cliente: "Ana Sousa", estado: "pendente",
  linhas: [{ produto: "prod-caneca", quantidade: 2, precoCentimos: 850 }] });
await servico.registar({ id: "enc-2", cliente: "Rui Lopes", estado: "pendente",
  linhas: [{ produto: "prod-cha", quantidade: 3, precoCentimos: 450 }] });
await servico.registar({ id: "enc-3", cliente: "Ana Sousa", estado: "pendente",
  linhas: [{ produto: "prod-cafe", quantidade: 1, precoCentimos: 1290 }] });

await servico.pagar("enc-1", "MB-1001", "2026-03-03");
await servico.enviar("enc-1", "CTT-RR001");
await servico.pagar("enc-3", "MB-1002", "2026-03-04");

const falhas = [
  await servico.enviar("enc-2", "CTT-RR002"),
  await servico.pagar("enc-9", "MB-1003", "2026-03-04"),
];
for (const r of falhas) {
  if (!r.ok) console.log(descreverErro(r.erro));
}
// não é possível enviar enc-2: está pendente
// enc-9 não existe

for (const linha of formatar(await servico.relatorio())) console.log(linha);
// pendente    1   13.50 €
// paga        1   12.90 €
// enviada     1   17.00 €
// cancelada   0    0.00 €
// Ana Sousa: 29.90 €
// Rui Lopes: 13.50 €

type Igual<A, B> =
  (<T>() => T extends A ? 1 : 2) extends (<T>() => T extends B ? 1 : 2) ? true : false;
type Esperar<T extends true> = T;

type IdEncomenda = `enc-${number}`;
type DataISO = `${number}-${number}-${number}`;
interface BaseEncomenda { readonly id: IdEncomenda; readonly cliente: string }
interface Pendente extends BaseEncomenda { readonly estado: "pendente" }
interface Paga extends BaseEncomenda { readonly estado: "paga"; readonly referencia: string; readonly pagaEm: DataISO }
interface Enviada extends Omit<Paga, "estado"> { readonly estado: "enviada"; readonly codigoEnvio: string }
interface Cancelada extends BaseEncomenda { readonly estado: "cancelada"; readonly motivo: string }
type Encomenda = Pendente | Paga | Enviada | Cancelada;
type Estado = Encomenda["estado"];
type EncomendaEm<S extends Estado> = Extract<Encomenda, { estado: S }>;

declare function pagar(e: Pendente, referencia: string, pagaEm: DataISO): Paga;
declare function enviar(e: Paga, codigoEnvio: string): Enviada;
declare function cancelar(e: EncomendaEm<"pendente" | "paga">, motivo: string): Cancelada;

// 1. Testes positivos: os tipos derivados são exatamente os esperados
type testes = [
  Esperar<Igual<Estado, "pendente" | "paga" | "enviada" | "cancelada">>,
  Esperar<Igual<EncomendaEm<"paga">, Paga>>,
  Esperar<Igual<Parameters<typeof enviar>[0], Paga>>,
  Esperar<Igual<ReturnType<typeof cancelar>, Cancelada>>,
  Esperar<Igual<Enviada["pagaEm"], DataISO>>,
];

// 2. Testes negativos: o que o compilador TEM de recusar
declare const pendente: Pendente;
declare const cancelada: Cancelada;
declare const enviada: Enviada;

// Uma encomenda cancelada não pode ser enviada
// @ts-expect-error
enviar(cancelada, "CTT-RR999");

// Uma pendente também não: primeiro tem de ser paga
// @ts-expect-error
enviar(pendente, "CTT-RR999");

// Uma enviada já não se cancela
// @ts-expect-error
cancelar(enviada, "arrependimento");

// IDs com o formato errado não passam
// @ts-expect-error
const idMau: IdEncomenda = "encomenda-1";

// Uma Paga sem referência não é uma Paga
// @ts-expect-error
const incompleta: Paga = { id: "enc-1", cliente: "Ana", estado: "paga", pagaEm: "2026-03-03" };

// Os campos são readonly: nada de mudar o estado "por fora"
declare const paga: Paga;
// @ts-expect-error
paga.estado = "enviada";

// E o caminho certo compila sem uma única asserção
const caminhoFeliz: Enviada = enviar(pagar(pendente, "MB-1", "2026-03-03"), "CTT-RR1");

