type IdEncomenda = `enc-${number}`;
type DataISO = `${number}-${number}-${number}`;
interface BaseEncomenda { readonly id: IdEncomenda; readonly cliente: string }
interface Pendente extends BaseEncomenda { readonly estado: "pendente" }
interface Paga extends BaseEncomenda { readonly estado: "paga"; readonly referencia: string; readonly pagaEm: DataISO }
interface Enviada extends Omit<Paga, "estado"> { readonly estado: "enviada"; readonly codigoEnvio: string }
interface Cancelada extends BaseEncomenda { readonly estado: "cancelada"; readonly motivo: string }
// O estado novo: só se chega lá a partir de uma encomenda enviada
interface Devolvida extends Omit<Enviada, "estado"> {
  readonly estado: "devolvida";
  readonly devolvidaEm: DataISO;
  readonly reembolsoCentimos: number;
}
type Encomenda = Pendente | Paga | Enviada | Cancelada | Devolvida;

function devolver(e: Enviada, devolvidaEm: DataISO, reembolsoCentimos: number): Devolvida {
  return { ...e, estado: "devolvida", devolvidaEm, reembolsoCentimos };
}

// Depois de acrescentar Devolvida à união, o default deixou de compilar
// (Type 'Devolvida' is not assignable to type 'never') até existir este case
function descrever(e: Encomenda): string {
  switch (e.estado) {
    case "pendente":
      return `${e.id}: à espera de pagamento`;
    case "paga":
      return `${e.id}: paga (ref. ${e.referencia})`;
    case "enviada":
      return `${e.id}: enviada com o código ${e.codigoEnvio}`;
    case "cancelada":
      return `${e.id}: cancelada (${e.motivo})`;
    case "devolvida":
      return `${e.id}: devolvida em ${e.devolvidaEm}, reembolso de ${(e.reembolsoCentimos / 100).toFixed(2)} €`;
    default: {
      const impossivel: never = e;
      return impossivel;
    }
  }
}

