type Igual<A, B> =
  (<T>() => T extends A ? 1 : 2) extends (<T>() => T extends B ? 1 : 2) ? true : false;
type Esperar<T extends true> = T;

interface Pendente { readonly id: string; readonly estado: "pendente" }
interface Paga { readonly id: string; readonly estado: "paga"; readonly referencia: string }
interface Enviada { readonly id: string; readonly estado: "enviada"; readonly codigoEnvio: string }
interface Cancelada { readonly id: string; readonly estado: "cancelada"; readonly motivo: string }
type Encomenda = Pendente | Paga | Enviada | Cancelada;
type Estado = Encomenda["estado"];

// A máquina de estados escrita uma vez, como tipo
type Transicoes = {
  pendente: "paga" | "cancelada";
  paga: "enviada" | "cancelada";
  enviada: never;
  cancelada: never;
};

// Garante que a tabela cobre todos os estados e só aponta para estados válidos
type TabelaValida = Esperar<Transicoes extends Record<Estado, Estado> ? true : false>;

// Estados de onde se pode sair e estados finais, derivados da tabela
type Ativo = { [S in Estado]: Transicoes[S] extends never ? never : S }[Estado];
type Final = Exclude<Estado, Ativo>;

// Pode ir de De para Para?
type PodeIr<De extends Estado, Para extends Estado> = Para extends Transicoes[De] ? true : false;

type testes = [
  Esperar<Igual<Ativo, "pendente" | "paga">>,
  Esperar<Igual<Final, "enviada" | "cancelada">>,
  Esperar<Igual<PodeIr<"pendente", "paga">, true>>,
  Esperar<Igual<PodeIr<"cancelada", "enviada">, false>>,
  Esperar<Igual<PodeIr<"pendente", "enviada">, false>>,
];

