type IdEncomenda = `enc-${number}`;
type Estado = "pendente" | "paga" | "enviada" | "cancelada";
interface ResumoEncomenda {
  readonly id: IdEncomenda;
  readonly cliente: string;
  readonly estado: Estado;
  readonly totalCentimos: number;
}

const pausa = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

class RepositorioEmMemoria<T extends { readonly id: string }> {
  private readonly itens = new Map<T["id"], T>();

  constructor(private readonly latenciaMs: number = 3) {}

  async guardar(item: T): Promise<void> {
    await pausa(this.latenciaMs);
    this.itens.set(item.id, item);
  }

  // O valor tem de ter o tipo do campo escolhido: T[K]
  async procurar<K extends keyof T>(campo: K, valor: T[K]): Promise<T[]> {
    await pausa(this.latenciaMs);
    return [...this.itens.values()].filter((item) => item[campo] === valor);
  }
}

const repo = new RepositorioEmMemoria<ResumoEncomenda>();
await repo.guardar({ id: "enc-1", cliente: "Ana Sousa", estado: "enviada", totalCentimos: 1700 });
